    axis = 0
    for i, key in enumerate(tup):
        if i >= self.obj.ndim:
            raise IndexingError('Too many indexers')
        if com.is_null_slice(key):
            axis += 1
            continue
        retval = getattr(retval, self.name)._getitem_axis(key, axis=axis)
        if retval.ndim < self.ndim:
            axis -= 1
        axis += 1
    return retval

